function ContactForm() {
    const [formData, setFormData] = useState({
        fullName: '',
        email: '',
        phone: ''
    });

    const [errors, setErrors] = useState({
        fullName: '',
        email: '',
        phone: ''
    });

    const [submitted, setSubmitted] = useState(false);

    const validateEmail = (email) => {
        const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return re.test(String(email).toLowerCase());
    };

    const validatePhone = (phone) => {
        if (!phone.trim()) return true; // Optional field
        // Basic check for international phone format
        const re = /^\+\d{1,3}[\s\-\(\)\d]{6,15}$/;
        return re.test(phone.trim());
    };

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));

        // Clear error when user types
        if (errors[name]) {
            setErrors(prev => ({ ...prev, [name]: '' }));
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();

        let newErrors = {};
        let isValid = true;

        if (!formData.fullName.trim()) {
            newErrors.fullName = 'Full name is required.';
            isValid = false;
        }

        if (!formData.email.trim()) {
            newErrors.email = 'Email address is required.';
            isValid = false;
        } else if (!validateEmail(formData.email)) {
            newErrors.email = 'Please enter a valid email address.';
            isValid = false;
        }

        if (formData.phone && !validatePhone(formData.phone)) {
            newErrors.phone = 'Please enter a valid phone number (e.g. +1 555 123 4567).';
            isValid = false;
        }

        setErrors(newErrors);

        if (isValid) {
            setSubmitted(true);
            // Simulate API call
            console.log('Form data submitted:', formData);
        }
    };

    if (submitted) {
        return (
            <div className="success-message">
                <h2>Message Sent!</h2>
                <p>Thank you for contacting support. We will get back to you shortly.</p>
                <button 
                    onClick={() => {
                        setSubmitted(false);
                        setFormData({ fullName: '', email: '', phone: '' });
                    }} 
                    className="btn-secondary"
                >
                    Submit another request
                </button>
            </div>
        );
    }

    return (
        <div className="form-container">
            <h2>Contact Support</h2>
            <p className="subtitle">Need help? Fill out the form below and our team will get back to you as soon as possible.</p>

            <form onSubmit={handleSubmit} noValidate>
                <div className="form-field">
                    <label htmlFor="fullName">Full Name</label>
                    <input
                        type="text"
                        id="fullName"
                        name="fullName"
                        value={formData.fullName}
                        onChange={handleChange}
                        className={errors.fullName ? 'error-input' : ''}
                        placeholder="e.g. Jane Doe"
                    />
                    {errors.fullName && <span className="error-text">{errors.fullName}</span>}
                </div>

                <div className="form-field">
                    <label htmlFor="email">Email Address</label>
                    <input
                        type="email"
                        id="email"
                        name="email"
                        value={formData.email}
                        onChange={handleChange}
                        className={errors.email ? 'error-input' : ''}
                        placeholder="e.g. jane@example.com"
                    />
                    {errors.email && <span className="error-text">{errors.email}</span>}
                </div>

                <div className="form-field">
                    <label htmlFor="phone">Phone Number (Optional)</label>
                    <input
                        type="tel"
                        id="phone"
                        name="phone"
                        value={formData.phone}
                        onChange={handleChange}
                        className={errors.phone ? 'error-input' : ''}
                        placeholder="e.g. +1 555 123 4567"
                    />
                    <span className="helper-text">Format: +1 (Country Code) followed by your number (e.g. +1 555 123 4567)</span>
                    {errors.phone && <span className="error-text">{errors.phone}</span>}
                </div>

                <button type="submit" className="btn-primary">Submit Request</button>
            </form>
        </div>
    );
}

const root = ReactDOM.createRoot(document.getElementById('root'));
